use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// Promedio de la columna `column` (0-indexada) de un CSV, en streaming.
/// No carga el archivo en memoria: usa un buffer de 1 MiB y reusa la
/// misma `String` por línea. Kahan compensation evita la deriva de f64.
pub fn column_average(
    path: impl AsRef<Path>,
    column: usize,
    has_header: bool,
) -> io::Result<f64> {
    let file = File::open(path)?;
    let mut reader = BufReader::with_capacity(1024 * 1024, file);

    let mut sum = 0.0f64;
    let mut comp = 0.0f64; // compensación Kahan
    let mut count: u64 = 0;

    let mut line = String::new();
    let mut lineno: u64 = 0;
    let mut skipped: u64 = 0;

    loop {
        line.clear();
        if reader.read_line(&mut line)? == 0 {
            break;
        }
        lineno += 1;
        if has_header && lineno == 1 {
            continue;
        }

        let trimmed = line.trim_end_matches(|c| c == '\n' || c == '\r');
        if trimmed.is_empty() {
            continue;
        }

        let Some(field) = field_at(trimmed, column) else {
            skipped += 1;
            continue;
        };

        match field.trim().parse::<f64>() {
            Ok(v) if v.is_finite() => {
                let y = v - comp;
                let t = sum + y;
                comp = (t - sum) - y;
                sum = t;
                count += 1;
            }
            _ => skipped += 1,
        }
    }

    if skipped > 0 {
        eprintln!("filas descartadas: {skipped}");
    }
    if count == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "no hay valores numéricos en la columna pedida",
        ));
    }

    Ok(sum / count as f64)
}

/// Extrae el campo `target` de una línea CSV mínima (comillas dobles,
/// comas y `""` como escape). Sin comillas la mayoría de los campos se
/// resuelven como slice; solo se aloca el campo devuelto.
fn field_at(line: &str, target: usize) -> Option<String> {
    let bytes = line.as_bytes();
    let mut idx = 0usize;
    let mut start = 0usize;
    let mut in_quotes = false;
    let mut i = 0usize;

    while i < bytes.len() {
        match bytes[i] {
            b'"' => {
                if in_quotes && i + 1 < bytes.len() && bytes[i + 1] == b'"' {
                    i += 2; // comilla escapada dentro de campo citado
                    continue;
                }
                in_quotes = !in_quotes;
                i += 1;
            }
            b',' if !in_quotes => {
                if idx == target {
                    return Some(parse_field(&line[start..i]));
                }
                idx += 1;
                start = i + 1;
                i += 1;
            }
            _ => i += 1,
        }
    }

    if idx == target {
        Some(parse_field(&line[start..]))
    } else {
        None
    }
}

fn parse_field(raw: &str) -> String {
    let s = raw.trim();
    let b = s.as_bytes();
    if b.len() >= 2 && b[0] == b'"' && b[b.len() - 1] == b'"' {
        let inner = &s[1..s.len() - 1];
        let mut out = String::with_capacity(inner.len());
        let mut chars = inner.chars().peekable();
        while let Some(c) = chars.next() {
            if c == '"' && chars.peek() == Some(&'"') {
                chars.next();
                out.push('"');
            } else {
                out.push(c);
            }
        }
        out
    } else {
        s.to_string()
    }
}

fn main() -> io::Result<()> {
    let avg = column_average("datos.csv", 2, true)?;
    println!("promedio: {avg}");
    Ok(())
}
